// PWM LED Fading
// Smoothly fades an LED up to full brightness and back down using analogWrite().

const int LED_PIN = 9; // must be a PWM (~) pin

void setup() {
  // no pinMode() call needed for analogWrite() on most boards, but it's
  // harmless and good habit to include it explicitly:
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  // fade up: 0 (off) to 255 (full brightness)
  for (int brightness = 0; brightness <= 255; brightness++) {
    analogWrite(LED_PIN, brightness);
    delay(8);
  }

  // fade down: 255 back to 0
  for (int brightness = 255; brightness >= 0; brightness--) {
    analogWrite(LED_PIN, brightness);
    delay(8);
  }
}
